insert into public.game_config (key, value) values ('flavour', '{"moods":{"thriving":"{name} {is} glowing like a lamp in a cottage window.","happy":"{name} {is} pottering about, humming to the kettle.","sleepy":"{name}''s eyelids are drooping. The quilt is turned down and waiting.","hungry":"{name} keeps wandering past the pantry door. Something to eat, please.","bored":"{name} {is} drumming {their} fingers on the windowsill. Time for an adventure in the wood.","magical":"{name} {is} fizzing with magic. The dried herbs are swaying on their own.","offended":"{name} {has} pulled {their} hood right down and gone quiet. A kind word and a warm drink would help."},"joined":"{name} has joined the coven. Another chair at the hearth.","ritualComplete":"The hedge rustled its approval.","dailyTitle":"Something on the doorstep","dailyBody":"A basket on the step: today''s acorns and a little find from the wood.","welcome":"The cottage is yours, {name}"}'::jsonb) on conflict (key) do update set value = excluded.value;
