insert into public.game_config (key, value) values ('gift_treats', '[{"id":"treat_tea","name":"Nettle tea","cost":8,"effects":{"nourishment":15,"joy":15,"energy":10}},{"id":"treat_pie","name":"Blackberry pie","cost":6,"effects":{"nourishment":30,"energy":5}},{"id":"treat_honey","name":"Wild honey","cost":5,"effects":{"nourishment":25,"joy":8}},{"id":"treat_posy","name":"Lavender posy","cost":10,"effects":{"joy":25,"magic":5}}]'::jsonb) on conflict (key) do update set value = excluded.value;
